import{_ as t,o,c as a,ag as r}from"./chunks/framework.DMVuHR7L.js";const i="/web-logcat/staging/docs/assets/empty-state.BNPnTB8y.png",u=JSON.parse('{"title":"Connecting a device","description":"","frontmatter":{},"headers":[],"relativePath":"features/connecting.md","filePath":"features/connecting.md","lastUpdated":1778207311000}'),s={name:"features/connecting.md"};function n(d,e,h,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="connecting-a-device" tabindex="-1">Connecting a device <a class="header-anchor" href="#connecting-a-device" aria-label="Permalink to &quot;Connecting a device&quot;">​</a></h1><p>WebLogcat talks to the phone directly from the browser via <strong>WebUSB</strong>. There is no <code>adb</code> install on the laptop, no Android Studio, no proxy server — permission is granted through Chromium&#39;s standard device chooser and the on-device authorisation prompt.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>Chromium-based browser</strong>: Chrome, Edge, Brave, Opera, Arc. Firefox and Safari don&#39;t ship WebUSB, so the <strong>Connect a device</strong> button is disabled there.</li><li>The site served over <strong>HTTPS</strong> or from <code>localhost</code>. The hosted versions at <code>https://gabrielhuff.github.io/web-logcat/</code> (production) and <code>https://gabrielhuff.github.io/web-logcat/staging/</code> (staging) qualify; so does <code>npm run dev</code>.</li><li>An <strong>Android device</strong> with USB debugging enabled in <em>Settings → System → Developer options</em>.</li></ul><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p><img src="'+i+'" alt="Connecting flow"></p><ol><li>Plug the device in with a data-capable USB cable.</li><li>Click <strong>Connect a device</strong>. The browser shows its device chooser; pick your phone.</li><li>The phone shows the standard <em>Allow USB debugging?</em> prompt the first time. Tick <strong>Always allow from this computer</strong> if you want subsequent connects to be silent.</li><li>The dashboard mounts with a single Logcat tile filling the viewport. The topbar shows the device model and serial; the connection dot is green for real devices and amber for the simulator. Use <strong>+ Add widget</strong> to add more tiles.</li></ol><p>The browser remembers the WebUSB grant the same way it remembers any other permission — the second connect from the same browser+device pair is silent.</p><h2 id="switching-devices" tabindex="-1">Switching devices <a class="header-anchor" href="#switching-devices" aria-label="Permalink to &quot;Switching devices&quot;">​</a></h2><p>The device pill in the topbar opens a picker showing every device the browser has paired in this session, plus the simulator if it&#39;s been used. Pick a row to switch; the previous stream stays warm in the background so you can flip back without re-authorising.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause / fix</th></tr></thead><tbody><tr><td>Chooser is empty</td><td>Verify USB debugging is on, the device is unlocked, and the cable is data-capable. Replug and reload.</td></tr><tr><td>Pairing prompt never appears on the phone</td><td>Some OEMs hide it behind a notification. Pull down the shade.</td></tr><tr><td><code>Connect a device</code> is disabled</td><td>You&#39;re on Firefox / Safari, or the page isn&#39;t served from HTTPS / localhost.</td></tr><tr><td>Connection drops on screen-off</td><td>Some manufacturers cut USB after sleep. Disable screen-locked-off behaviour or keep the screen awake.</td></tr><tr><td>Mirror shows &quot;device not supported&quot;</td><td>Mirror needs <code>scrcpy</code> v2.7 capabilities. Older / very locked-down devices may refuse the push.</td></tr></tbody></table><p>If the chooser shows the phone but the connect step fails, check the browser console — the toast message comes from <code>friendlyConnectError()</code> in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/adb.ts" target="_blank" rel="noreferrer"><code>lib/adb.ts</code></a> and the underlying error usually points at the cause (timeout, permission denied, USB endpoint busy).</p><h2 id="don-t-have-a-phone" tabindex="-1">Don&#39;t have a phone? <a class="header-anchor" href="#don-t-have-a-phone" aria-label="Permalink to &quot;Don&#39;t have a phone?&quot;">​</a></h2><p>Click <strong>fake data</strong> on the empty state. The dashboard runs against the <a href="./simulator">simulated stream</a> so every widget renders against in-memory fixtures.</p>',15)])])}const b=t(s,[["render",n]]);export{u as __pageData,b as default};
